fn main() -> Void {
    let weights: Int[] = [5, 8, 6, 7, 4, 9];
    let n: Int = length(weights);
    let total: Int = 1 << n;
    let within: Int = 0;
    let best: Int = 0;
    let ways: Int = 0;

    loop mask in 0..total {
        let sum: Int = 0;
        loop i in 0..n {
            if (mask & (1 << i)) != 0 {
                sum = sum + weights[i];
            }
        }
        if sum <= 20 {
            within = within + 1;
            if sum > best {
                best = sum;
                ways = 1;
            } else if sum == best {
                ways = ways + 1;
            }
        }
    }

    fx {
        println("Subsets within limit: ", within);
        println("Best total: ", best);
        println("Ways to reach best: ", ways);
    }
    ret;
}

fn main() -> Void {
    let grid: Text[] = [
        "....S.",
        "..T...",
        "......",
        ".S...T",
        "...X..",
        "T....."
    ];

    let trainCount: Int = 0;
    let blockedCount: Int = 0;
    let signalCount: Int = 0;

    let trainRows: Int[] = [];
    let trainCols: Int[] = [];
    let signalRows: Int[] = [];
    let signalCols: Int[] = [];
    let blockedRows: Int[] = [];

    loop r in 0..6 {
        loop c in 0..6 {
            let ch: Text = grid[r][c];
            if ch == "T" {
                trainCount = trainCount + 1;
                trainRows = trainRows + [r];
                trainCols = trainCols + [c];
            }
            if ch == "X" {
                blockedCount = blockedCount + 1;
                blockedRows = blockedRows + [r];
            }
            if ch == "S" {
                signalCount = signalCount + 1;
                signalRows = signalRows + [r];
                signalCols = signalCols + [c];
            }
        }
    }

    let totalDist: Int = 0;
    loop i in 0..trainCount {
        let tr: Int = trainRows[i];
        let tc: Int = trainCols[i];
        let nearest: Int = 999;
        loop j in 0..signalCount {
            let sr: Int = signalRows[j];
            let sc: Int = signalCols[j];
            let d: Int = abs(tr - sr) + abs(tc - sc);
            if d < nearest {
                nearest = d;
            }
        }
        totalDist = totalDist + nearest;
    }

    let avgDist: Real = 0.0;
    if trainCount > 0 {
        avgDist = totalDist * 1.0 / trainCount;
    }

    let rowBlockedCount: Int = 0;
    loop i in 0..trainCount {
        let tr: Int = trainRows[i];
        let inBlockedRow: Bool = false;
        loop br in blockedRows {
            if br == tr {
                inBlockedRow = true;
                break;
            }
        }
        if inBlockedRow {
            rowBlockedCount = rowBlockedCount + 1;
        }
    }

    fx {
        println("Trains: ", trainCount);
        println("Blocked: ", blockedCount);
        println("AvgSignalDist: ", format_float(avgDist, 2));
        println("TrainsInBlockedRow: ", rowBlockedCount);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [12, 8, -1, 15, 10, 7],
        [9, 11, 14, -1, 6, 13],
        [-1, 10, 8, 12, 9, -1],
        [15, 7, 11, 10, 13, 8],
        [6, -1, 9, 14, 7, 12],
        [11, 13, -1, 8, 15, 10]
    ];

    let availableCount: Int = 0;
    let fastestTime: Int = 999999;
    let pairMinSum: Int = 999999;
    let total: Int = 0;

    loop r in 0..6 {
        let rowMin: Int = 999999;
        let rowSecond: Int = 999999;
        loop c in 0..6 {
            let t: Int = grid[r][c];
            if t != -1 {
                availableCount = availableCount + 1;
                total = total + t;
                if t < fastestTime {
                    fastestTime = t;
                }
                if t < rowMin {
                    rowSecond = rowMin;
                    rowMin = t;
                } else if t < rowSecond {
                    rowSecond = t;
                }
            }
        }
        if rowSecond < 999999 {
            let s: Int = rowMin + rowSecond;
            if s < pairMinSum {
                pairMinSum = s;
            }
        }
    }

    loop c in 0..6 {
        let colMin: Int = 999999;
        let colSecond: Int = 999999;
        loop r in 0..6 {
            let t: Int = grid[r][c];
            if t != -1 {
                if t < colMin {
                    colSecond = colMin;
                    colMin = t;
                } else if t < colSecond {
                    colSecond = t;
                }
            }
        }
        if colSecond < 999999 {
            let s: Int = colMin + colSecond;
            if s < pairMinSum {
                pairMinSum = s;
            }
        }
    }

    let avg: Real = total * 1.0 / availableCount;
    let avgRounded: Real = round_to(avg, 2);

    fx {
        println("AvailableCount: ", availableCount);
        println("FastestTime: ", fastestTime);
        println("PairMinSum: ", pairMinSum);
        println("AvgTime: ", format_float(avgRounded, 2));
    }
    ret;
}

fn main() -> Void {
    let pars: Int[][] = [
        [2, 3, 2, 4, 3, 2],
        [3, 4, 3, 2, 4, 3],
        [2, 3, 4, 3, 2, 4],
        [4, 2, 3, 4, 3, 2],
        [3, 4, 2, 3, 4, 3],
        [2, 3, 4, 2, 3, 4]
    ];
    let strokes: Int[][] = [
        [2, 4, 1, 5, 3, 2],
        [5, 3, 4, 2, 6, 3],
        [1, 3, 5, 4, 2, 5],
        [6, 2, 3, 5, 4, 1],
        [4, 5, 2, 3, 5, 4],
        [3, 2, 6, 1, 3, 5]
    ];

    let totalStrokes: Int = 0;
    let totalPar: Int = 0;
    let underPar: Int = 0;
    let bestDiff: Int = 0;
    let worstDiff: Int = 0;

    loop r in 0..6 {
        loop c in 0..6 {
            let p: Int = pars[r][c];
            let s: Int = strokes[r][c];
            totalStrokes = totalStrokes + s;
            totalPar = totalPar + p;
            if s < p {
                underPar = underPar + 1;
            }
            let diff: Int = p - s;
            if diff > bestDiff {
                bestDiff = diff;
            }
            let over: Int = s - p;
            if over > worstDiff {
                worstDiff = over;
            }
        }
    }

    fx {
        println("TotalStrokes: ", totalStrokes);
        println("TotalPar: ", totalPar);
        println("UnderPar: ", underPar);
        println("BestDiff: ", bestDiff);
        println("WorstDiff: ", worstDiff);
    }
    ret;
}

@pure
fn isPalindrome(n: Int) -> Bool {
    let s: Text = int_to_text(n);
    let len: Int = string_len(s);
    loop i in 0..(len div 2) {
        if s[i] != s[len - 1 - i] {
            ret false;
        }
    }
    ret true;
}

@pure
fn digitSum(n: Int) -> Int {
    let total: Int = 0;
    let x: Int = n;
    loop {
        if x == 0 {
            break;
        }
        total = total + (x % 10);
        x = x div 10;
    }
    ret total;
}

@pure
fn isPrime(n: Int) -> Bool {
    if n < 2 {
        ret false;
    }
    if n == 2 {
        ret true;
    }
    if n % 2 == 0 {
        ret false;
    }
    let i: Int = 3;
    loop i <= n div i {
        if n % i == 0 {
            ret false;
        }
        i = i + 2;
    }
    ret true;
}

@pure
fn isPerfect(n: Int) -> Bool {
    if !isPalindrome(n) {
        ret false;
    }
    ret isPrime(digitSum(n));
}

fn main() -> Void {
