    fx {
        println("High Value Count: ", highCount);
    }
    ret;
}

@pure
fn countDivisors(n: Int) -> Int {
    let count: Int = 0;
    loop i in 1..n + 1 {
        if n % i == 0 {
            count = count + 1;
        }
    }
    ret count;
}

@pure
fn isFertile(n: Int) -> Bool {
    ret countDivisors(n) == 4;
}

fn main() -> Void {
