        fx {
            println("Plot ", i + 1, ": ", label);
        }
    }
    ret;
}

fn main() -> Void {
    let names: Text[] = ["Smith, John", "Doe, Jane", "o'brien, patrick", "Lee, Kim", "Garcia, Maria", "Chen, Wei"];
    let count: Int = 0;

    loop name in names {
        let commaIdx: Int = index_of(name, ",");
        if commaIdx == -1 {
            fx {
                println(name, " => N/A");
            }
        } else {
            let lastPart: Text = trim(name[0..commaIdx]);
            let firstPart: Text = trim(name[commaIdx + 1..]);
            let lastInitial: Text = upper(lastPart[0]);
            let firstInitial: Text = upper(firstPart[0]);
            count = count + 1;
            fx {
                println(name, " => ", lastInitial, ".", firstInitial);
            }
        }
    }

    fx {
        println("INITIALS GENERATED: ", count);
    }

    ret;
}

type Customer {
    name: Text = "";
    points: Int = 0;
    tier: Text = "";
}

fn main() -> Void {
    let customers: Customer[] = [
        new Customer { name: "Ana", points: 340, tier: "Silver" },
        new Customer { name: "Ben", points: 780, tier: "Gold" },
        new Customer { name: "Cleo", points: 210, tier: "Bronze" },
        new Customer { name: "Dev", points: 560, tier: "Silver" },
        new Customer { name: "Eve", points: 890, tier: "Gold" }
    ];

    let totalPoints: Int = 0;
    let topName: Text = "";
    let topPoints: Int = 0;
    let goldPoints: Int = 0;
    let silverCount: Int = 0;
    let bronzeNames: Text[] = [];

    loop c in customers {
        totalPoints = totalPoints + c.points;
        if c.points > topPoints {
            topPoints = c.points;
            topName = c.name;
        }
        if c.tier == "Gold" {
            goldPoints = goldPoints + c.points;
        }
        if c.tier == "Silver" {
            silverCount = silverCount + 1;
        }
        if c.tier == "Bronze" {
            bronzeNames = bronzeNames + [c.name];
        }
    }

    let bronzeLine: Text = "none";
    if length(bronzeNames) > 0 {
        bronzeLine = join(bronzeNames, ", ");
    }

    fx {
        println("LOYALTY REPORT");
        println("Total points: ", totalPoints);
        println("Top customer: ", topName, " (", topPoints, " points)");
        println("Gold points: ", goldPoints);
        println("Silver count: ", silverCount);
        println("Bronze members: ", bronzeLine);
    }
    ret;
}

fn main() -> Void {
    let line: Text[] = ["P1", "P2", "P3", "P4"];
