fn formatTime(totalMinutes: Int) -> Text {
    let h: Int = totalMinutes div 60;
    let m: Int = totalMinutes % 60;
    let hText: Text = int_to_text(h);
    let mText: Text = int_to_text(m);
    let hPadded: Text = if h < 10 { "0" + hText } else { hText };
    let mPadded: Text = if m < 10 { "0" + mText } else { mText };
    ret hPadded + ":" + mPadded;
}

fn main() -> Void {
