fn to_base(n: Int, b: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let digits: Int[] = [];
    let v: Int = n;
    loop {
        let d: Int = v % b;
        digits = digits + [d];
        v = v div b;
        if v == 0 {
            break;
        }
    }
    let rep: Text = "";
    loop i in 0..length(digits) {
        rep = rep + int_to_text(digits[length(digits) - 1 - i]);
    }
    ret rep;
}

