        fx {
            println("STAR ", m, " BASE ", b, " -> ", rep, " | LAST DIGIT ", last);
        }
    }

    let bestDigit: Int = 0;
    let bestCount: Int = counts[0];
    loop d in 1..10 {
        if counts[d] > bestCount {
            bestCount = counts[d];
            bestDigit = d;
        }
    }

    fx {
        println("LAST DIGIT ", int_to_text(bestDigit), " COUNT ", bestCount);
    }
    ret;
