fn isValid(code: Text) -> Bool {
    if string_len(code) != 5 {
        ret false;
    }
    if code[2] != "-" {
        ret false;
    }
    let a: Text = code[0];
    let b: Text = code[1];
    let c: Text = code[3];
    let d: Text = code[4];
    if !is_upper(a) || !is_upper(b) || !is_upper(c) || !is_upper(d) {
        ret false;
    }
    if a == c && b == d {
        ret false;
    }
    ret true;
}

