@pure
fn isValidSeat(s: Text) -> Bool {
    if string_len(s) != 4 {
        ret false;
    }
    let deck: Text = s[0];
    if deck != "A" && deck != "B" && deck != "C" {
        ret false;
    }
    if s[1] != "-" {
        ret false;
    }
    let num: Int = parse_int(s[2..4]);
    if num < 1 || num > 30 {
        ret false;
    }
    ret true;
}

