fn nextZone(current: Text, cmp: Text) -> Text {
    if current == "AHEAD" {
        if cmp == "FAST" {
            ret "AHEAD";
        }
        if cmp == "EVEN" {
            ret "ONPACE";
        }
        ret "BEHIND";
    }
    if current == "ONPACE" {
        if cmp == "FAST" {
            ret "AHEAD";
        }
        if cmp == "EVEN" {
            ret "ONPACE";
        }
        ret "BEHIND";
    }
    if cmp == "FAST" {
        ret "ONPACE";
    }
    ret "BEHIND";
}

