fn main() -> Void {
    let counts: Int[] = [12, 3, 7, 7, 7, 1, 4, 9, 2, 5];
    let n: Int = length(counts);
    let windowSize: Int = 3;
    let windowCount: Int = n - windowSize + 1;
    let totals: Int[] = [];
    loop i in 0..windowCount {
        let total: Int = 0;
        loop j in 0..windowSize {
            total = total + counts[i + j];
        }
        totals = totals + [total];
    }

    let maxTotal: Int = totals[0];
    let maxStart: Int = 1;
    let minTotal: Int = totals[0];
    let minStart: Int = 1;
    loop i in 1..windowCount {
        if totals[i] > maxTotal {
            maxTotal = totals[i];
            maxStart = i + 1;
        }
        if totals[i] < minTotal {
            minTotal = totals[i];
            minStart = i + 1;
        }
    }

    let line: Text = "Windows: ";
    loop i in 0..windowCount {
        if i > 0 {
            line = line + ", ";
        }
        line = line + int_to_text(totals[i]);
    }

    fx {
        println(line);
        println("Max window total: ", maxTotal);
        println("Max window start: ", maxStart);
        println("Min window total: ", minTotal);
        println("Min window start: ", minStart);
    }
    ret;
}

fn main() -> Void {
    let stops: Int[] = [1, 3, 4, 7, 8, 9, 10];
    let n: Int = length(stops);
    let gaps: Int[] = [];
    loop i in 0..n - 1 {
        gaps = gaps + [stops[i + 1] - stops[i]];
    }

    let gapText: Text = "";
    loop i in 0..length(gaps) {
        if i > 0 {
            gapText = gapText + ", ";
        }
        gapText = gapText + int_to_text(gaps[i]);
    }

    let maxGap: Int = gaps[0];
    let maxIdx: Int = 0;
    loop i in 1..length(gaps) {
        if gaps[i] > maxGap {
            maxGap = gaps[i];
            maxIdx = i;
        }
    }

    let skipped: Int = 10 - n;
    let direct: Int = 0;
    loop g in gaps {
        if g == 1 {
            direct = direct + 1;
        }
    }

    fx {
        println("Gaps: ", gapText);
        println("Max gap: ", maxGap);
        println("Max gap after terminal: ", stops[maxIdx]);
        println("Skipped terminals: ", skipped);
        println("Direct hops: ", direct);
    }
    ret;
}

