fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc = toon_parse("{\"rooms\":[{\"name\":\"Dinosaurs\",\"visitors\":142,\"rating\":4.6},{\"name\":\"Space\",\"visitors\":98,\"rating\":4.9},{\"name\":\"Ocean\",\"visitors\":75,\"rating\":4.1},{\"name\":\"Art\",\"visitors\":120,\"rating\":4.7},{\"name\":\"History\",\"visitors\":55,\"rating\":3.8}],\"target\":100}");
    let root: ToonNode = toon_root(doc);
    let rooms: ToonNode = toon_key(root, "rooms");
    let target: Int = toon_get_int_or(root, "target", 0);

    let total: Int = 0;
    let busiestName: Text = "";
    let busiestCount: Int = -1;
    let ratingSum: Real = 0.0;
    let roomCount: Int = 0;

    loop i in 0..toon_len(rooms) {
        let room: ToonNode = toon_at(rooms, i);
        let name: Text = toon_get_text_or(room, "name", "");
        let visitors: Int = toon_get_int_or(room, "visitors", 0);
        let rating: Real = toon_get_real_or(room, "rating", 0.0);

        total = total + visitors;
        ratingSum = ratingSum + rating;
        roomCount = roomCount + 1;

        if visitors > busiestCount {
            busiestCount = visitors;
            busiestName = name;
        }
    }

    fx {
        println("Total visitors: ", total);
        println("Busiest room: ", busiestName);
    }

    loop i in 0..toon_len(rooms) {
        let room: ToonNode = toon_at(rooms, i);
        let name: Text = toon_get_text_or(room, "name", "");
        let visitors: Int = toon_get_int_or(room, "visitors", 0);
        if visitors >= target {
            fx {
                println(name, " meets target");
            }
        }
    }

    let avg: Real = ratingSum / roomCount;
    fx {
        println("Average rating: ", format_float(avg, 2));
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("garden_plots.txt"); }

    let totalPlots: Int = 0;
    let totalArea: Int = 0;
    let totalWater: Int = 0;
    let lowCount: Int = 0;
    let plotIds: Text[] = [];
    let plotWater: Int[] = [];
    let plotArea: Int[] = [];

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        let plotId: Text = parts[0];
        let area: Int = parse_int(parts[1]);
        let water: Int = parse_int(parts[2]);
        let status: Text = parts[3];

        totalPlots = totalPlots + 1;
        totalArea = totalArea + area;
        totalWater = totalWater + water;
        if status == "LOW" {
            lowCount = lowCount + 1;
        }
        plotIds = plotIds + [plotId];
        plotWater = plotWater + [water];
        plotArea = plotArea + [area];
    }

    let avgWater: Real = 0.0;
    if totalArea > 0 {
        avgWater = totalWater * 1.0 / totalArea;
    }

    fx {
        println("Total plots: ", totalPlots);
        println("Total area: ", totalArea);
        println("Total water: ", totalWater);
        println("Average water per square meter: ", format_float(avgWater, 2));
        println("Low status plots: ", lowCount);
        println("Water per square meter by plot:");
        loop i in 0..length(plotIds) {
            let w: Real = plotWater[i] * 1.0 / plotArea[i];
            println("  ", plotIds[i], ": ", format_float(w, 2));
        }
    }
    ret;
}

