        let order: ToonNode = toon_at(orders, i);
        let student: Text = toon_get_text_or(order, "student", "?");
        let items: ToonNode = toon_key_or(order, "items", toon_null());
        let total: Real = 0.0;
        loop j in 0..toon_len(items) {
            let item: ToonNode = toon_at(items, j);
            total = total + toon_real_value(item);
            itemsSold = itemsSold + 1;
        }
        revenue = revenue + total;
        if total <= freeLimit {
            if freeNames == "" {
                freeNames = student;
            } else {
                freeNames = freeNames + "," + student;
            }
        }
