fn main() -> Void {
    let grid: Text[] = ["OOOXO", "OOXOO", "OXOOO", "OOOXO", "OOOOO"];
    let n: Int = 5;
    let dp: Int[][] = [];
    loop r in 0..n {
        let row: Int[] = [];
        loop c in 0..n {
            row = row + [0];
        }
        dp = dp + [row];
    }

    if grid[0][0] == "O" {
        dp[0][0] = 1;
    }

    loop r in 0..n {
        loop c in 0..n {
            if r == 0 && c == 0 {
                continue;
            }
            if grid[r][c] == "X" {
                continue;
            }
            let ways: Int = 0;
            if r > 0 {
                ways = ways + dp[r - 1][c];
            }
            if c > 0 {
                ways = ways + dp[r][c - 1];
            }
            dp[r][c] = ways;
        }
    }

    fx {
        println("PATHS=", dp[n - 1][n - 1]);
    }
    ret;
}

