fn main() -> Void {
    let codes: Text[] = ["SCI", "ART", "HIS", "MUS", "LIT"];
    let dd: Int[] = [14, 7, 99, 42, 55];
    let ddd: Int[] = [205, 112, 34, 670, 881];
    let total: Int = 0;

    loop i in 0..5 {
        let d1: Int = dd[i] div 10;
        let d2: Int = dd[i] % 10;
        let d3: Int = ddd[i] div 100;
        let d4: Int = (ddd[i] div 10) % 10;
        let d5: Int = ddd[i] % 10;
        let ds: Int = d1 + d2 + d3 + d4 + d5;
        total = total + ds;

        let ddText: Text = int_to_text(dd[i]);
        let dddText: Text = int_to_text(ddd[i]);

        let ddPadded: Text = "";
        if dd[i] < 10 {
            ddPadded = "0" + ddText;
        } else {
            ddPadded = ddText;
        }

        let dddPadded: Text = "";
        if ddd[i] < 10 {
            dddPadded = "00" + dddText;
        } else if ddd[i] < 100 {
            dddPadded = "0" + dddText;
        } else {
            dddPadded = dddText;
        }

        let code: Text = ddPadded + "." + dddPadded + " " + codes[i];

        fx {
            println(code, "|", ddPadded, "|", dddPadded, "|", ds, "|", codes[i]);
        }
    }

    fx {
        println("TOTAL_SUM=", total);
    }
    ret;
}

fn main() -> Void {
    let names: Text[] = ["A", "B", "C", "D"];
    let delays: Int[] = [5, 0, 12, 7];

    let onTime: Int = 0;
    let minor: Int = 0;
    let major: Int = 0;
    let total: Int = 0;
    let worstIdx: Int = 0;

    loop i in 0..length(delays) {
        let d: Int = delays[i];
        total = total + d;
        if d == 0 {
            onTime = onTime + 1;
        } else if d >= 1 && d <= 5 {
            minor = minor + 1;
        } else {
            major = major + 1;
        }
        if d > delays[worstIdx] {
            worstIdx = i;
        }
    }

    fx {
        println("On time: ", onTime);
        println("Minor: ", minor);
        println("Major: ", major);
        println("Worst train: ", names[worstIdx]);
        println("Total delay: ", total, " minutes");
    }
    ret;
}

