fn main() -> Void {
    let rooms: Int[][] = [
        [5, 5, 4, 5, 3],
        [4, 3, 5, 4, 2],
        [3, 5, 5, 5, 4],
        [5, 4, 3, 3, 5]
    ];
    let roomNames: Text[] = ["Room 101", "Room 102", "Room 201", "Room 202"];
    let dayNames: Text[] = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];
    let numRooms: Int = length(rooms);
    let numDays: Int = 5;
    let dayTotals: Int[] = [0, 0, 0, 0, 0];
    let grandTotal: Int = 0;

    loop r in 0..numRooms {
        let rowTotal: Int = 0;
        loop d in 0..numDays {
            rowTotal = rowTotal + rooms[r][d];
            dayTotals[d] = dayTotals[d] + rooms[r][d];
        }
        grandTotal = grandTotal + rowTotal;
        fx {
            println(roomNames[r], ": ", rowTotal);
        }
    }

    loop d in 0..numDays {
        fx {
            println(dayNames[d], ": ", dayTotals[d]);
        }
    }

    let maxDay: Int = 0;
    loop d in 1..numDays {
        if dayTotals[d] > dayTotals[maxDay] {
            maxDay = d;
        }
    }
    fx {
        println("Busiest day: ", dayNames[maxDay]);
    }

    let avg: Real = grandTotal * 1.0 / (numRooms * numDays);
    fx {
        println("Average per room per day: ", format_float(avg, 2));
    }

    ret;
}

fn main() -> Void {
    let commands: Text[] = ["ON", "TOGGLE", "TOGGLE", "OFF", "ON", "ON", "TOGGLE", "OFF", "TOGGLE", "TOGGLE"];
    let isOn: Bool = false;
    let totalOn: Int = 0;
    let transitions: Int = 0;

    loop cmd in commands {
        let prev: Bool = isOn;
        if cmd == "ON" {
            isOn = true;
        } else if cmd == "OFF" {
            isOn = false;
        } else {
            isOn = !isOn;
        }
        if isOn != prev {
            transitions = transitions + 1;
        }
        if isOn {
            totalOn = totalOn + 1;
        }
    }

