fn main() -> Void {
    let readings: Real[] = [7.0, 7.8, 7.2, 5.9, 6.8, 8.3, 7.1, 7.4, 6.2, 7.0];
    let state: Text = "GOOD";
    let goodCount: Int = 0;
    let watchCount: Int = 0;
    let criticalCount: Int = 0;
    let criticalToWatch: Int = 0;

    loop r in readings {
        let prev: Text = state;
        if state == "GOOD" {
            if r >= 6.5 && r <= 7.5 {
                state = "GOOD";
            } else {
                state = "WATCH";
            }
        } else if state == "WATCH" {
            if r >= 6.5 && r <= 7.5 {
                state = "GOOD";
            } else if r < 6.0 || r > 8.0 {
                state = "CRITICAL";
            } else {
                state = "WATCH";
            }
        } else {
            if r >= 6.5 && r <= 7.5 {
                state = "WATCH";
                criticalToWatch = criticalToWatch + 1;
            } else {
                state = "CRITICAL";
            }
        }

        if state == "GOOD" {
            goodCount = goodCount + 1;
        } else if state == "WATCH" {
            watchCount = watchCount + 1;
        } else {
            criticalCount = criticalCount + 1;
        }
    }

    fx {
        println("FinalState=", state);
        println("GoodCount=", goodCount);
        println("WatchCount=", watchCount);
        println("CriticalCount=", criticalCount);
        println("CriticalToWatch=", criticalToWatch);
    }
    ret;
}

