fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("dock_status.txt"); }

    let available: Int[] = [];
    let faultyCount: Int = 0;
    let highestOccupied: Int = -1;

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        let slot: Int = parse_int(parts[0]);
        let bikes: Int = parse_int(parts[1]);
        let faulty: Bool = parse_bool(parts[2]);

        if faulty {
            faultyCount = faultyCount + 1;
        }
        if bikes == 1 {
            if slot > highestOccupied {
                highestOccupied = slot;
            }
        }
        if bikes == 1 && !faulty {
            available = available + [slot];
        }
    }

    let availableText: Text = "";
    if length(available) == 0 {
        availableText = "none";
    } else {
        loop i in 0..length(available) {
            if i > 0 {
                availableText = availableText + ",";
            }
            availableText = availableText + int_to_text(available[i]);
        }
    }

    let highestText: Text = "none";
    if highestOccupied >= 0 {
        highestText = int_to_text(highestOccupied);
    }

    fx {
        println("Available slots: ", availableText);
        println("Available count: ", length(available));
        println("Faulty count: ", faultyCount);
        println("Highest occupied slot: ", highestText);
    }
    ret;
}

