fn main() -> Void {
    let lines: Text[] = [
        "PLANT=rose;POT=12;PRICE=9.99;STOCK=5",
        "PLANT=rose;POT=15;PRICE=14.50;STOCK=3",
        "PLANT=tulip;POT=10;PRICE=6.75;STOCK=8",
        "PLANT=tulip;POT=12;PRICE=9.25;STOCK=4",
        "PLANT=fern;POT=14;PRICE=11.00;STOCK=6",
        "PLANT=fern;POT=18;PRICE=16.75;STOCK=2"
    ];

    let plants: Text[] = [];
    let values: Real[] = [];

    loop line in lines {
        let parts: Text[] = split(line, ";");
        let plantPart: Text = parts[0];
        let pricePart: Text = parts[2];
        let stockPart: Text = parts[3];

        let plant: Text = plantPart[6..];
        let price: Real = parse_float(pricePart[6..]);
        let stock: Int = parse_int(stockPart[6..]);

        let found: Bool = false;
        loop i in 0..length(plants) {
            if plants[i] == plant {
                values[i] = values[i] + price * stock;
                found = true;
                break;
            }
        }
        if !found {
            plants = plants + [plant];
            values = values + [price * stock];
        }
    }

    let n: Int = length(plants);
    let sortedPlants: Text[] = sorted(plants);

    loop i in 0..n {
        let plant: Text = sortedPlants[i];
        let total: Real = 0.0;
        loop j in 0..n {
            if plants[j] == plant {
                total = total + values[j];
            }
        }
        let rounded: Real = round_to(total, 2);
        fx {
            println(plant, " value=", format_float(rounded, 2));
        }
    }

    ret;
}

