type Session {
    name: Text = "";
    calories: Int = 0;
    rank: Int = 0;
}

fn main() -> Void {
    let sessions: Session[] = [
        new Session { name: "Morning Run", calories: 320 },
        new Session { name: "Yoga", calories: 140 },
        new Session { name: "Swimming", calories: 280 },
        new Session { name: "Cycling", calories: 320 },
        new Session { name: "Weight Training", calories: 210 },
        new Session { name: "HIIT", calories: 350 },
        new Session { name: "Stretching", calories: 60 },
        new Session { name: "Rowing", calories: 280 }
    ];

    let n: Int = length(sessions);
    let used: Bool[] = [false; n];
    let rank: Int = 1;

    loop r in 1..n + 1 {
        let bestIdx: Int = -1;
        loop i in 0..n {
            if !used[i] {
                if bestIdx == -1 {
                    bestIdx = i;
                } else {
                    if sessions[i].calories > sessions[bestIdx].calories {
                        bestIdx = i;
                    }
                }
            }
        }
        used[bestIdx] = true;
        sessions[bestIdx].rank = r;
    }

    let order: Int[] = [];
    loop r in 1..n + 1 {
        loop i in 0..n {
            if sessions[i].rank == r {
                order = order + [i];
            }
        }
    }

    loop i in 0..n {
        let idx: Int = order[i];
        fx {
            println(sessions[idx].name, ": ", sessions[idx].calories, " kcal #", sessions[idx].rank);
        }
    }

    ret;
}

