            totals = totals + [0];
        }

        if flag == "yes" {
            let i: Int = index_of(names, name);
            totals[i] = totals[i] + score;
            sum = sum + score;
            submitted = submitted + 1;
            if score >= 70 {
                passCount = passCount + 1;
            }
        }
    }

    fx {
        loop i in 0..length(names) {
            println("Student ", names[i], ": ", totals[i]);
        }
        println("Passing scores: ", passCount);
        let avg: Real = 0.0;
        if submitted > 0 {
            avg = sum * 1.0 / submitted;
        }
        println("Average submitted: ", format_float(avg, 1));
    }
    ret;
