fn main() -> Void {
    let lines: Text[] = [
        "Northbound express to Riverton departs from platform two",
        "Local service stopping at Millbrook and Oakdale now boarding",
        "Delayed train to Harrowgate will depart from platform five"
    ];

    let words: Text[] = [];
    let lineNums: Int[] = [];

    loop li in 0..length(lines) {
        let parts: Text[] = split(lines[li], " ");
        loop w in parts {
            if w != "" {
                let found: Bool = false;
                loop j in 0..length(words) {
                    if words[j] == w {
                        found = true;
                        break;
                    }
                }
                if !found {
                    words = words + [w];
                    lineNums = lineNums + [li + 1];
                } else {
                    loop j in 0..length(words) {
                        if words[j] == w {
                            lineNums[j] = lineNums[j] * 10 + (li + 1);
                            break;
                        }
                    }
                }
            }
        }
    }

    loop i in 0..length(words) {
        let num: Int = lineNums[i];
        let parts: Int[] = [];
        let temp: Int = num;
        loop {
            parts = parts + [temp % 10];
            temp = temp div 10;
            if temp == 0 {
                break;
            }
        }
        let out: Text = "";
        loop k in 0..length(parts) {
            let idx: Int = length(parts) - 1 - k;
            if k > 0 {
                out = out + ",";
            }
            out = out + int_to_text(parts[idx]);
        }
        fx {
            println(words[i], ": ", out);
        }
    }
    ret;
}

