fn main() -> Void {
    let binTotals: Int[] = [5, 7, 4];
    let proportions: Int[][] = [
        [2, 1, 3, 4],
        [1, 2, 1, 0],
        [0, 3, 2, 1]
    ];
    let shelfTotals: Int[] = [0, 0, 0, 0];

    loop b in 0..3 {
        let propSum: Int = 0;
        loop s in 0..4 {
            propSum = propSum + proportions[b][s];
        }
        loop s in 0..4 {
            let num: Int = binTotals[b] * proportions[b][s];
            let q: Int = num div propSum;
            let r: Int = num % propSum;
            let rounded: Int = q;
            if 2 * r >= propSum {
                rounded = q + 1;
            }
            shelfTotals[s] = shelfTotals[s] + rounded;
        }
    }

    fx {
        println("A: ", shelfTotals[0]);
        println("B: ", shelfTotals[1]);
        println("C: ", shelfTotals[2]);
        println("D: ", shelfTotals[3]);
    }
    ret;
}

@pure
fn digitSum(n: Int) -> Int {
    let s: Int = 0;
    let x: Int = n;
    loop {
        let d: Int = x % 10;
        s = s + d;
        x = x div 10;
        if x == 0 {
            break;
        }
    }
    ret s;
}

fn main() -> Void {
    let periods: Int[] = [3, 5, 2, 8, 1, 7, 4, 6];
    let sums: Int[] = [];
    loop p in periods {
        sums = sums + [digitSum(p)];
    }

    let total: Int = sum(sums);
    let evenCount: Int = 0;
    let oddCount: Int = 0;
    loop s in sums {
        if s % 2 == 0 {
            evenCount = evenCount + 1;
        } else {
            oddCount = oddCount + 1;
        }
    }

    let maxSum: Int = max_of(sums);
    let minSum: Int = min_of(sums);

    let sumsTextParts: Text[] = [];
    loop s in sums {
        sumsTextParts = sumsTextParts + [int_to_text(s)];
    }
    let sumsText: Text = join(sumsTextParts, " ");

    fx {
        println("PeriodSums=", sumsText);
        println("TotalSum=", total);
        println("EvenCount=", evenCount);
        println("OddCount=", oddCount);
        println("MaxSum=", maxSum);
        println("MinSum=", minSum);
    }
    ret;
}

