fn stateName(s: Int) -> Text {
    if s == 0 {
        ret "Resting";
    }
    if s == 1 {
        ret "Rising";
    }
    if s == 2 {
        ret "Ready";
    }
    if s == 3 {
        ret "OverProofed";
    }
    ret "Baked";
}

fn next_state(s: Int, h: Text, t: Int) -> Int {
    if s == 0 {
        if h == "L" {
            ret 1;
        }
        if h == "M" {
            ret 1;
        }
        ret 2;
    }
    if s == 1 {
        if t == 1 {
            ret 3;
        }
        if h == "H" {
            ret 2;
        }
        ret 1;
    }
    if s == 2 {
        if t == 1 {
            ret 4;
        }
        ret 2;
    }
    if s == 3 {
        ret 4;
    }
    ret 0;
}

