fn main() -> Void {
    let delays: Int[] = [3, 0, 7, 3, 1, 0, 9, 4, 3, 1];
    let n: Int = length(delays);
    let maxDelay: Int = 0;
    loop i in 0..n {
        if delays[i] > maxDelay {
            maxDelay = delays[i];
        }
    }
    let count: Int[] = [0; maxDelay + 1];
    loop i in 0..n {
        count[delays[i]] = count[delays[i]] + 1;
    }
    loop i in 1..maxDelay + 1 {
        count[i] = count[i] + count[i - 1];
    }
    let output: Int[] = [0; n];
    loop i in n - 1..(-1) step -1 {
        let d: Int = delays[i];
        count[d] = count[d] - 1;
        output[count[d]] = i;
    }
    fx {
        loop i in 0..n {
            let idx: Int = output[i];
            println("Dep", idx + 1, ":", delays[idx]);
        }
    }
    ret;
}

