fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("recipes.json"); }
    let root: ToonNode = toon_root(doc);

    let recipes: ToonNode;
    if toon_is_arr(root) {
        recipes = root;
    } else {
        recipes = toon_key(root, "recipes");
    }

    let total: Int = toon_len(recipes);
    let veganCount: Int = 0;
    let totalMinutes: Int = 0;
    let fastestTitle: Text = "";
    let fastestMinutes: Int = 0;
    let biggestVeganTitle: Text = "";
    let biggestVeganServings: Int = 0;

    loop i in 0..total {
        let row: ToonNode = toon_at(recipes, i);
        let title: Text = toon_get_text_or(row, "title", "");
        let minutes: Int = toon_get_int_or(row, "minutes", 0);
        let servings: Int = toon_get_int_or(row, "servings", 0);
        let isVegan: Bool = toon_get_bool_or(row, "vegan", false);

        totalMinutes = totalMinutes + minutes;

        if isVegan {
            veganCount = veganCount + 1;
            if servings > biggestVeganServings || (servings == biggestVeganServings && title < biggestVeganTitle) {
                biggestVeganServings = servings;
                biggestVeganTitle = title;
            }
        }

        if i == 0 || minutes < fastestMinutes || (minutes == fastestMinutes && title < fastestTitle) {
            fastestMinutes = minutes;
            fastestTitle = title;
        }
    }

    let avg: Real = 0.0;
    if total > 0 {
        avg = totalMinutes * 1.0 / total;
    }
    let avgRounded: Real = round_to(avg, 1);

    fx {
        println("Recipes: ", total);
        println("Vegan: ", veganCount);
        println("Avg minutes: ", format_float(avgRounded, 1));
        println("Fastest: ", fastestTitle);
        println("Biggest vegan: ", biggestVeganTitle);
    }

    toon_close(doc);
    ret;
}

