fn main() -> Void {
    let visits: Text[] = ["A1", "A2", "B1", "A1", "B2", "A2", "A1", "B1", "A1", "B2", "A2", "A1", "B1", "A1", "B2"];
    let counts: Map[Text, Int] = {};
    let order: Text[] = [];

    loop cell in visits {
        if !has(counts, cell) {
            counts[cell] = 0;
            order = order + [cell];
        }
        counts[cell] = counts[cell] + 1;
    }

    let n: Int = length(order);
    let sorted: Text[] = [];
    let used: Bool[] = [false; n];

    loop i in 0..n {
        let best: Int = -1;
        loop j in 0..n {
            if !used[j] {
                if best == -1 {
                    best = j;
                } else {
                    if counts[order[j]] > counts[order[best]] {
                        best = j;
                    }
                }
            }
        }
        sorted = sorted + [order[best]];
        used[best] = true;
    }

    fx {
        loop cell in sorted {
            println(cell, ": ", counts[cell]);
        }
    }
    ret;
}

