@pure
fn binom(n: Int, k: Int) -> Int {
    if k < 0 {
        ret 0;
    }
    if k > n {
        ret 0;
    }
    if k == 0 {
        ret 1;
    }
    if k == n {
        ret 1;
    }
    if k > n - k {
        k = n - k;
    }
    let result: Int = 1;
    loop i in 0..k {
        result = result * (n - i) div (i + 1);
    }
    ret result;
}

