fn main() -> Void {
    let temps: Int[] = [21, 18, 24, 24, 19, 27, 22];
    let n: Int = length(temps);

    loop i in 1..n {
        let key: Int = temps[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if temps[j] > key {
                temps[j + 1] = temps[j];
                j = j - 1;
            } else {
                break;
            }
        }
        temps[j + 1] = key;
    }

    let line: Text = "";
    loop i in 0..n {
        if i > 0 {
            line = line + " ";
        }
        line = line + int_to_text(temps[i]);
    }

    let median: Real;
    if n % 2 == 1 {
        median = temps[n div 2] * 1.0;
    } else {
        median = (temps[n div 2 - 1] + temps[n div 2]) * 1.0 / 2.0;
    }

    fx {
        println(line);
        println(format_float(median, 1));
    }
    ret;
}

