    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let visitors: ToonNode = toon_key(root, "visitors");
    let n: Int = toon_len(visitors);

    let adults: Int = 0;
    let children: Int = 0;
    let ratingSum: Int = 0;

    let exhibitNames: Text[] = [];
    let exhibitCounts: Int[] = [];

