    loop i in 0..toon_len(root) {
        let row: ToonNode = toon_at(root, i);
        let name: Text = toon_get_text_or(row, "name", "?");
        let origin: Text = toon_get_text_or(row, "origin", "?");
        let weight: Real = toon_get_real_or(row, "weight_kg", 0.0);
        let label: Text = if weight > 1.0 { "heavy" } else { "light" };
        fx {
            println(name, " from ", origin, ": ", label);
        }
    }

    toon_close(doc);
    ret;
}

