@pure
fn isPrime(n: Int) -> Bool {
    if n < 2 {
        ret false;
    }
    if n == 2 {
        ret true;
    }
    if n % 2 == 0 {
        ret false;
    }
    let d: Int = 3;
    loop d * d <= n {
        if n % d == 0 {
            ret false;
        }
        d = d + 2;
    }
    ret true;
}

@pure
fn fare(km: Int) -> Int {
    let f: Int = 150;
    if km > 10 {
        f = f + (km - 10) * 25;
    }
    if km % 7 == 0 {
        f = f - 20;
    }
    if isPrime(km) {
        f = f + 30;
    }
    ret f;
}

