fn main() -> Void {
    let stalls: Int[] = [0, 0, 0];
    let queue: Int[] = [];
    let maxQueue: Int = 0;
    let served: Int = 0;
    let stall0Used: Int = 0;

    let events: Int[][] = [
        [0, 1],
        [1, 1],
        [2, 1],
        [0, -1],
        [1, -1],
        [0, 1],
        [2, -1],
        [1, 1],
        [2, 1],
        [0, -1],
        [1, -1],
        [2, -1]
    ];

    loop i in 0..length(events) {
        let stall: Int = events[i][0];
        let typ: Int = events[i][1];

        if typ == 1 {
            if stalls[stall] == 0 {
                stalls[stall] = 1;
                served = served + 1;
                if stall == 0 {
                    stall0Used = 1;
                }
            } else {
                queue = queue + [stall];
                if length(queue) > maxQueue {
                    maxQueue = length(queue);
                }
            }
        } else {
            if stalls[stall] == 1 {
                stalls[stall] = 0;
                if length(queue) > 0 {
                    let nextStall: Int = queue[0];
                    queue = queue[1..];
                    stalls[nextStall] = 1;
                    served = served + 1;
                    if nextStall == 0 {
                        stall0Used = 1;
                    }
                }
            }
        }
    }

    let emptyStalls: Int = 0;
    loop s in 0..3 {
        if stalls[s] == 0 {
            emptyStalls = emptyStalls + 1;
        }
    }

    fx {
        println("max_queue=", maxQueue);
        println("served=", served);
        println("stall0_used=", stall0Used);
        println("empty_stalls=", emptyStalls);
    }
    ret;
}

