fn main() -> Void {
    let settings: Text[] = ["Delicates", "Cotton", "Permanent Press", "Towels"];
    let durations: Int[] = [40, 60, 50, 70];
    let events: Text[] = ["SELECT", "SELECT", "START", "TICK", "TICK", "TICK", "TICK", "TICK", "TICK", "TICK", "TICK", "SELECT", "START", "TICK"];

    let selected: Int = 0;
    let running: Bool = false;
    let remaining: Int = 0;
    let beeps: Int = 0;
    let lastSetting: Text = "";
    let lastDuration: Int = 0;

    loop i in 0..length(events) {
        let ev: Text = events[i];
        if ev == "SELECT" {
            selected = (selected + 1) % 4;
        }
        if ev == "START" {
            if !running {
                running = true;
                remaining = durations[selected];
                lastSetting = settings[selected];
                lastDuration = durations[selected];
            }
        }
        if ev == "TICK" {
            if running {
                remaining = remaining - 10;
                if remaining <= 0 {
                    remaining = 0;
                    running = false;
                    beeps = beeps + 1;
                    selected = 0;
                }
            }
        }
    }

    fx {
        println("LastSetting: ", lastSetting);
        println("LastDuration: ", lastDuration);
        println("Remaining: ", remaining);
        println("Beeps: ", beeps);
    }
    ret;
}

fn main() -> Void {
    let events: Text[] = ["CODE", "CODE", "ENTER", "STOCK", "STOCK", "EXIT", "CODE", "ENTER", "STOCK", "JAM", "CODE", "ENTER", "EXIT", "VEND", "VEND", "CODE"];
    let state: Text = "Normal";
    let codeCount: Int = 0;
    let stockCount: Int = 0;
    let vendCount: Int = 0;
    let serviceEntries: Int = 0;

    loop ev in events {
        if ev == "CODE" {
            if state == "Normal" {
                codeCount = codeCount + 1;
                if codeCount >= 2 {
                    state = "Service";
                    codeCount = 0;
                    serviceEntries = serviceEntries + 1;
                }
            } else if state == "Error" {
                state = "Normal";
                codeCount = 0;
            }
        } else {
            codeCount = 0;
            if ev == "ENTER" {
                // ignored
            } else if ev == "STOCK" {
                if state == "Service" {
                    stockCount = stockCount + 1;
                }
            } else if ev == "EXIT" {
                if state == "Service" {
                    state = "Normal";
                }
            } else if ev == "JAM" {
                if state == "Service" or state == "Normal" {
                    state = "Error";
                }
            } else if ev == "VEND" {
                if state == "Normal" {
                    vendCount = vendCount + 1;
                }
            }
        }
    }

    fx {
        println("FinalState: ", state);
        println("StockCount: ", stockCount);
        println("VendCount: ", vendCount);
        println("ServiceEntries: ", serviceEntries);
    }
    ret;
}

