    let totalQty: Int = 0;
    let wornQty: Int = 0;
    let maxBorrowDays: Int = 0;
    let longLoanItems: Int = 0;

    let nameTotals: Map[Text, Int] = {};

    loop i in 0..toon_len(items) {
        let item: ToonNode = toon_at(items, i);
        let name: Text = toon_get_text_or(item, "name", "");
