    let root: ToonNode = toon_root(doc);
    let recipes: ToonNode = toon_key(root, "recipes");
    let avoid: ToonNode = toon_key(root, "avoid");

    let safeCount: Int = 0;
    let unsafeCount: Int = 0;
    let fastestTime: Int = 999999;
    let titles: Text[] = [];

    loop i in 0..toon_len(recipes) {
        let recipe: ToonNode = toon_at(recipes, i);
        let title: Text = toon_get_text_or(recipe, "title", "");
        let time: Int = toon_get_int_or(recipe, "time", 0);
        let ingredients: ToonNode = toon_key(recipe, "ingredients");

        let isSafe: Bool = true;
        loop j in 0..toon_len(ingredients) {
            let ing: ToonNode = toon_at(ingredients, j);
            let ingText: Text = toon_text_value(ing);
            loop k in 0..toon_len(avoid) {
                let avoidItem: ToonNode = toon_at(avoid, k);
                let avoidText: Text = toon_text_value(avoidItem);
                if ingText == avoidText {
                    isSafe = false;
                }
            }
        }

        if isSafe {
            safeCount = safeCount + 1;
            titles = titles + [title];
            if time < fastestTime {
                fastestTime = time;
            }
        } else {
            unsafeCount = unsafeCount + 1;
        }
    }

    let titlesLine: Text = join(titles, ", ");

    fx {
        println("Safe recipes: ", safeCount);
        println("Titles: ", titlesLine);
        println("Fastest safe time: ", fastestTime);
        println("Unsafe count: ", unsafeCount);
    }

    toon_close(doc);
    ret;
}

