fn main() -> Void {
    let messages: Text[] = [
        "high wind warning for the coast",
        "flood watch along the river",
        "heat advisory for the valley",
        "wind and rain advisory for the coast",
        "flood warning lifted for the river"
    ];
    let queries: Text[] = ["wind", "flood", "advisory", "flood warning"];

    loop q in queries {
        let found: Int[] = [];
        loop i in 0..length(messages) {
            if contains(messages[i], q) {
                found = found + [i + 1];
            }
        }
        if length(found) == 0 {
            fx {
                println(q, ": none");
            }
        } else {
            let parts: Text[] = [];
            loop n in found {
                parts = parts + [int_to_text(n)];
            }
            fx {
                println(q, ": ", join(parts, " "));
            }
        }
    }
    ret;
}

