fn main() -> Void {
    let dp: Int[] = [0; 8];
    dp[0] = 1;
    loop i in 1..8 {
        if i == 4 {
            dp[i] = 0;
        } else {
            let ways: Int = 0;
            if i - 1 >= 0 {
                ways = ways + dp[i - 1];
            }
            if i - 3 >= 0 {
                ways = ways + dp[i - 3];
            }
            dp[i] = ways;
        }
    }
    fx {
        println("Ways: ", dp[7]);
    }
    ret;
}

fn main() -> Void {
    let days: Text[] = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let grid: Text[][] = [
        ["MATH", "ENG", "ART", "GYM", "FREE"],
        ["ENG", "MATH", "FREE", "GYM", "ART"],
        ["ART", "FREE", "MATH", "ENG", "GYM"],
        ["GYM", "ART", "ENG", "MATH", "FREE"],
        ["FREE", "GYM", "ART", "ENG", "MATH"],
        ["MATH", "FREE", "GYM", "ART", "FREE"]
    ];

    let busiestDay: Text = "";
    let busiestCount: Int = -1;
    let quietestDay: Text = "";
    let quietestCount: Int = 999;
    let mathTotal: Int = 0;
    let artTotal: Int = 0;
    let freeTotal: Int = 0;
    let busyCells: Int = 0;

    loop r in 0..length(days) {
        let dayBusy: Int = 0;
        loop c in 0..length(grid[r]) {
            let cell: Text = grid[r][c];
            if cell == "MATH" {
                mathTotal = mathTotal + 1;
            }
            if cell == "ART" {
                artTotal = artTotal + 1;
            }
            if cell == "FREE" {
                freeTotal = freeTotal + 1;
            }
            if cell != "FREE" {
                dayBusy = dayBusy + 1;
                busyCells = busyCells + 1;
            }
        }
        if dayBusy > busiestCount {
            busiestCount = dayBusy;
            busiestDay = days[r];
        }
        if dayBusy < quietestCount {
            quietestCount = dayBusy;
            quietestDay = days[r];
        }
    }

    fx {
        println("Busiest day: ", busiestDay, " (", busiestCount, " periods)");
        println("Quietest day: ", quietestDay, " (", quietestCount, " periods)");
        println("MATH total: ", mathTotal);
        println("ART total: ", artTotal);
        println("FREE total: ", freeTotal);
        println("Busy cells: ", busyCells);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [1, 1, 0, 1],
        [1, 2, 0, 1],
        [0, 0, 1, 1],
        [1, 1, 1, 2],
        [0, 1, 1, 1],
        [1, 0, 1, 1]
    ];

    let rows: Int = length(grid);
    let cols: Int = length(grid[0]);

    let totalFree: Int = 0;
    let usableFree: Int = 0;
    let faulty: Int = 0;
    let occupied: Int = 0;
    let clearRows: Int = 0;

    loop r in 0..rows {
        let rowHasFaulty: Bool = false;
        loop c in 0..cols {
            let v: Int = grid[r][c];
            if v == 0 {
                totalFree = totalFree + 1;
                let hasFaultyNeighbor: Bool = false;
                if r > 0 && grid[r - 1][c] == 2 {
                    hasFaultyNeighbor = true;
                }
                if r < rows - 1 && grid[r + 1][c] == 2 {
                    hasFaultyNeighbor = true;
                }
                if c > 0 && grid[r][c - 1] == 2 {
                    hasFaultyNeighbor = true;
                }
                if c < cols - 1 && grid[r][c + 1] == 2 {
                    hasFaultyNeighbor = true;
                }
                if !hasFaultyNeighbor {
                    usableFree = usableFree + 1;
                }
            }
            if v == 1 {
                occupied = occupied + 1;
            }
            if v == 2 {
                faulty = faulty + 1;
                rowHasFaulty = true;
            }
        }
        if !rowHasFaulty {
            clearRows = clearRows + 1;
        }
    }

    fx {
        println("Total free spaces: ", totalFree);
        println("Usable free spaces: ", usableFree);
        println("Faulty sensors: ", faulty);
        println("Clear rows: ", clearRows);
        println("Occupied sensors: ", occupied);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [18, 22, 15, 20, 12],
        [25, 19, 21, 17, 14],
        [11, 23, 16, 24, 13],
        [20, 18, 22, 19, 10]
    ];

    let over: Int = 0;
    let full: Int = 0;
    let under: Int = 0;
    let total: Int = 0;

    loop r in 0..length(grid) {
        loop c in 0..length(grid[r]) {
            let v: Int = grid[r][c];
            total = total + v;
            if v > 20 {
                over = over + 1;
            } else if v == 20 {
                full = full + 1;
            } else {
                under = under + 1;
            }
        }
    }

    let util: Real = round_to(total * 100.0 / 400.0, 1);

    fx {
        println("Over capacity: ", over);
        println("Exactly full: ", full);
        println("Under capacity: ", under);
        println("Total enrolled: ", total);
        println("Utilization: ", format_float(util, 1), "%");
    }
    ret;
}
